// === Tab: mySketch ===
// =======================
//  P5.JS SKETCH COMPLETO
// =======================

let theShader;

function keyPressed() {
  if (key === 's' || key === 'S') {
    saveCanvas('captura', 'png');
  }
}

function preload() {
  theShader = createShader(vert, frag);
}

function setup() {
  createCanvas(windowWidth, windowHeight, WEBGL); // full screen
  noStroke();
  pixelDensity(1); // mantener calidad sin distorsión
}

function draw() {

// [SENTINEL 專家 2 修復] 音訊座標數值防禦
if(typeof window.simulatedMouseX === 'number' && isNaN(window.simulatedMouseX)) window.simulatedMouseX = width*0.5;
if(typeof window.simulatedMouseY === 'number' && isNaN(window.simulatedMouseY)) window.simulatedMouseY = height*0.5;

  shader(theShader);

  // pasar uniformes
  theShader.setUniform("u_resolution", [width, height]);
  theShader.setUniform("u_time", millis() / 1000.0); 
  theShader.setUniform("u_frame", frameCount);
  theShader.setUniform("u_mouse", [
    (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))/100.0,
    map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, height, 0)/100.0
  ]);

  rect(-width/2, -height/2, width, height); // cubre todo el canvas
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}

// === Tab: frag ===
// =======================
//  FRAGMENT SHADER
// =======================
const frag = `
#ifdef GL_ES
precision mediump float;
#endif

uniform vec2 u_resolution;
uniform float u_time;
uniform int u_frame;
uniform vec2 u_mouse;

#define pi 3.14159

float sdEquilateralTriangle( in vec2 p ) {
    const float k = sqrt(4.0);
    p.x = abs(p.x) - 1.;
    p.y = p.y + 1./k;
    if( p.x+k*p.y>0.0 ) p = vec2(p.x-k*p.y,-k*p.x-p.y)/4.0;
    p.x -= clamp( p.x, -3.0, 3.0 );
    return -length(p);
}

float sdBox( in vec2 p, in vec2 b ) {
    vec2 d = abs(p)-b;
    return length(max(d,0.0)) + min(max(d.x,d.y),0.0);
}

float thc(float a, float b) { return sin(a * cos(b)) / sin(a); }
float ths(float a, float b) { return cos(a * sin(b)) / cos(a); }

float arrow(vec2 uv) {
    float h = 0.25;
    h += 0.5 * thc(4.,-1. * length(uv) + 2. * atan(uv.y,uv.x) + u_time);
    h += 0.5 * (0.5 + 0.5 * thc(3., length(uv)*3. - u_time));
    float d = sdEquilateralTriangle(uv-vec2(0.,0.001 - h));
    float s = 1.-smoothstep(-0.1,0.1,d+0.5);
    float d2 = sdBox(uv - vec2(0.,-h), vec2(0.05,0.2));
    float s2 = 1.-smoothstep(-0.5,0.5,d2);
    s += s2;
    return s;
}

vec3 pal( float t, vec3 a, vec3 b, vec3 c, vec3 d ) {
    vec3 black = vec3(0.0, 0.0, 0.0);
    vec3 red   = vec3(0.6, 0.0, 0.0); // ← ya no se usa
    vec3 gray  = vec3(0.3, 0.3, 0.3);
    vec3 white = vec3(1.0, 1.0, 1.0);

    float mixVal = 0.5 + 0.5 * sin(t*6.28318);

    if (mixVal < 0.25) return black;
    else if (mixVal < 0.5) return gray;   // ← antes devolvía rojo
    else if (mixVal < 0.75) return gray;
    else return white * 0.4;
}


float h21 (vec2 a) { return fract(sin(dot(a.xy, vec2(12.9898, 78.233))) * 43758.5453123); }

vec2 rot(vec2 uv, float a) {
    mat2 mat = mat2(cos(a), -sin(a), 
                    sin(a), cos(a));
    return mat * uv;
}

float tri(float x) { return abs(fract(x) * 2.0 - 1.0); }

float lineGlitchMask(float angle, float time) {
    float id = floor((angle + pi) * 20.0);
    float seed = h21(vec2(id, floor(time * 0.5)));
    float active = step(0.02, 0.03 - seed);
    float t = fract(time * 0.5);
    float pulse = smoothstep(0.0, 0.2, t) * smoothstep(1.0, 0.7, t);
    return active * pulse;
}

void main() {
    // UV normalizado full screen
    vec2 uv = (gl_FragCoord.xy / u_resolution.xy) * 2.0 - 1.0;
    uv.x *= u_resolution.x / u_resolution.y; // mantener proporción

    // Breathe / temblor sin zoom
    uv += vec2(
        sin(u_time * 0.8) * 0.005,
        cos(u_time * 2.7) * 0.005
    );

    float slowT = u_time * 0.45;
    float speedVar = mix(0.4, 1.0, h21(vec2(floor(slowT * 0.3), 8.12)));

    float t1 = tri(uv.x * 3.5 + slowT * speedVar * 0.8);
    float t2 = tri(uv.y * 3.0 + slowT * speedVar * 0.6);
    float t3 = tri((uv.x + uv.y) * 2.0 + slowT * speedVar * 0.4);

    vec2 spike = vec2(
        (t1 - 0.5) * 0.02 + (t3 - 0.5) * 0.015,
        (t2 - 0.5) * 0.02 + (t3 - 0.5) * 0.015
    );

    uv += spike;

    float twitch = (h21(vec2(slowT * 2.3, slowT * 4.7)) - 0.5) * 0.01;
    uv += vec2(twitch, -twitch * 0.8);

    float a = atan(uv.y, uv.x);
    float r = log(length(uv));
    a = 100000. * a;

    float l = min(1., atan(0.2 * u_time)/0.95);
    r *= 0.6 + 0.25 * l * thc(1., 3. * a + 2. * length(uv) - u_time);

    float h = 2. + floor(0.5 * fract(0.01 * u_time)); 
    a = h * a;

    // GLITCH INTENSO FRECUENTE
    float glitch = lineGlitchMask(a * 0.00001, u_time);
    float burstSeed = h21(vec2(floor(u_time * 2.2), 99.91));
    float burstActive = step(0.70, burstSeed);
    float burstT = fract(u_time * 2.2);  
    float burstPulse = smoothstep(0.0, 0.15, burstT) * smoothstep(1.0, 0.75, burstT);
    vec2 burstShift = vec2(
        sin(u_time * 200.0 + a * 20.0) * 0.25,
        cos(u_time * 180.0 + a * 25.0) * 0.25
    );
    float jitter = (h21(uv * 80.0 + u_time * 15.0) - 0.5);
    vec2 jitterShift = vec2(jitter * 0.015, -jitter * 0.02);

    uv += 
          glitch * vec2(
              sin(u_time * 80.0 + a * 0.1) * 0.1,
              cos(u_time * 50.0 - a * 0.2) * 0.1
          )
        + burstActive * burstPulse * burstShift
        + jitterShift;

    uv = rot(uv, u_time +  2. * a + 6.1415 * sin(3. * r + a - u_time));

    float s = arrow(uv);
    s *= 1. + 0.01 * s;

    vec3 col = 0.25 * s + s * pal(
        thc(2., s + 2. * r + a - u_time) - 0.5 * u_time,
        vec3(1.), vec3(1.), vec3(1.), cos(s + u_time) * vec3(0.,1.,2.)/3.
    );
    col *= smoothstep(0.,0.1,2.25-length(uv));
    col = mix(col, vec3(1., .93, .92) * 0.4, smoothstep(0., 3.5, -r));

    float shimmer = (h21(vec2(u_time * 12.7, uv.x * 33.1)) - 0.5) * 0.25;
    col += shimmer;

    gl_FragColor = vec4(col,1.0);
}
`;

// === Tab: vert ===
// =======================
//  VERTEX SHADER
// =======================
const vert = `
attribute vec3 aPosition;
attribute vec2 aTexCoord;

void main() {
  vec4 positionVec4 = vec4(aPosition, 1.0);
  positionVec4.xy = positionVec4.xy * 2.0 - 1.0;
  gl_Position = positionVec4;
}
`;

